class os_developer_options
{
public:
    enum ints_t
    {
        INT_DEMO_MODE_TIMEOUT = 18,
        INT_DEMO_MODE_DURATION = 19
    };

    static os_developer_options *inst();
    int get_int(ints_t option) const;
};

class DemoModeManager
{
private:
    float totalTime;
    float timeoutDelay;
    float demoDuration;
    float demoTime;
    bool inDemo;
    bool played;
    bool demoStarted;
    void GoGame();
    char fname[24];
    bool wasInTitle;

public:
    void Init();
};

void DemoModeManager::Init()
{
	timeoutDelay = (float)os_developer_options::inst()->get_int(os_developer_options::INT_DEMO_MODE_TIMEOUT);
	demoDuration = (float)os_developer_options::inst()->get_int(os_developer_options::INT_DEMO_MODE_DURATION);

	if(timeoutDelay == 0)
		timeoutDelay = 30.0f;
	wasInTitle = false;
	totalTime = 0;
	demoStarted = false;
}
